  'page.legend.yellow_desc':    'People in social vulnerability and food insecurity who are hungry at home or on the street and need food.',
  'page.legend.blue_label':     'In blue',
  'page.legend.blue_desc':      'People or initiatives that receive food or resources to distribute in the community (soup kitchen, NGOs, volunteers) and need donations.',
