  'page.creators.heading':      'Mapa Fome content creators',
  'page.creators.iframe_title': 'Creators Mapa Fome',
  'page.thanks.a0':           '[REVISAR-HUMANO] In gratitude for the human, moral and ethical formation I received from my high-school Philosophy and Sociology teachers.',
  'page.thanks.a1':           '[REVISAR-HUMANO] After 10 years of having watched, learned and internalized our role as a society, I had the chance to act using accumulated knowledge and technologies.',
  'page.thanks.a2':           '[REVISAR-HUMANO] And the foundation for creating projects (field research and Project Manager) gained in the Projetão CIn UFPE course.',
  'page.thanks.a3':           '[REVISAR-HUMANO] It led to obtaining the tools needed to act on behalf of people who go hungry.',
  'page.thanks.a4':           '[REVISAR-HUMANO] And to give visibility, contributing alongside the kind-hearted people who routinely feed those who have no money to buy food.',
  'page.thanks.a5':           '[REVISAR-HUMANO] And to help food merchants reduce waste.',
  'page.thanks.a6':           '[REVISAR-HUMANO] And to motivate and offer tools for every human being to do their part and help on a recurring basis.',
  'page.thanks.a7':           '[REVISAR-HUMANO] Or, if not with food, by sharing information, letting those who need it and those who can help know that MAPA FOME exists.',
  'page.thanks.a8':           '[REVISAR-HUMANO] Without food, any human being dies prematurely. Failing to provide assistance, when it can be done without personal risk, constitutes the crime of Failure to Render Aid (Art. 135 of the Brazilian Penal Code).',
  'page.thanks.doc_lead':       '[REVISAR-HUMANO] For having aired the award-winning 13-minute short documentary by the Brazilian Jorge Furtado,',
  'page.timeline.t0_time':    '0–3 horas',
  'page.timeline.t0_conseq':  'Minimal change.',
  'page.timeline.t1_time':    '4–8 horas',
  'page.timeline.t1_conseq':  'More hunger, mild belly ache, a possible headache.',
  'page.timeline.t2_time':    '9–12 horas',
  'page.timeline.t2_conseq':  'Tiredness, irritability, stress and a headache.',
  'page.timeline.t3_time':    '13–16 horas',
  'page.timeline.t3_conseq':  'Trouble paying attention and concentrating.',
  'page.timeline.t4_time':    '17–24 horas',
  'page.timeline.t4_conseq':  'Low blood sugar: dizziness or shaking.',
  'page.timeline.t5_time':    '25–48 horas',
  'page.timeline.t5_conseq':  'Weakness and survival mode: the heart beats faster from lack of energy.',
  'page.timeline.t6_time':    '49–72 horas',
  'page.timeline.t6_conseq':  'The body starts using stored fat; the immune system weakens.',
  'page.timeline.t7_time':    '3–7 dias',
  'page.timeline.t7_conseq':  'Muscle starts being burned for energy. Lower motivation and productivity.',
  'page.timeline.t8_time':    '8–14 dias',
  'page.timeline.t8_conseq':  'The organs begin to suffer and the person gets sick far more easily.',
  'page.timeline.t9_time':    '15–21 dias',
  'page.timeline.t9_conseq':  'Life is in danger.',
  'page.timeline.t10_time':    '22+ dias',
  'page.timeline.t10_conseq':  'Extreme danger: the organs can stop working at any moment.',
