  'page.hungertable.conseq_0':   'Minimal change',
  'page.hungertable.conseq_1':   'You will feel hungrier and your belly will hurt a little, and you may get a headache',
  'page.hungertable.conseq_2':   'You will start to feel tired and grumpy, angry, irritable, stressed and you will have a headache',
  'page.hungertable.conseq_3':   'it will be harder to pay attention or concentrate',
  'page.hungertable.conseq_4':   'Your body will not have enough sugar, which will make you feel dizzy or SHAKY',
  'page.hungertable.conseq_5':   'You will feel weak and enter a high-stress situation and survival mode, your heart will beat faster because there is a lack of the energy that comes from food, so it tries to work double to keep the result going (delivering oxygen and nutrients to vital organs)',
  'page.hungertable.conseq_6':   'Your body will start to use stored energy (fat,...), which will make you feel tired and your immune system will not work as well, you get sick more easily',
  'page.hungertable.conseq_7':   'Muscles begin to be consumed as energy, you will feel very weak and your muscles will shrink. This is not good for your body, it damages the organism. Lower motivation or productivity',
  'page.hungertable.conseq_8':   'Your organs, which are important parts of your body, will be harmed and you will get sick much more easily',
  'page.hungertable.conseq_9':   'You will become very sick and your life will be in danger',
  'page.hungertable.conseq_10':  'You are in extreme danger because your body is not getting enough food, and your organs will stop working properly or stop at any moment',
