  'page.partners.back':            '← Map',
  'page.partners.title':           'Become a MAPA FOME partner',
  'page.partners.lead':            'MAPA FOME is a public, free and anonymous platform that lets any citizen, in three taps, map people facing food insecurity so that nearby volunteers can bring help in real time. Partner companies sustain the operation and earn honest visibility alongside active communities, without surveilling anyone.',
  'page.partners.how_title':       'How sponsorship works',
  'page.partners.how_step1':       'You choose a tier (neighborhood, city, state or national) and a time window.',
  'page.partners.how_step2':       'You send the PNG banner (150-character image contract + dignity checklist).',
  'page.partners.how_step3':       'We set up the campaign with a geographic center + radius + dates. It appears only to people within that radius.',
  'page.partners.how_step4_lead':  'Each month you get access to the ',
  'page.partners.how_step4_link':  'Marketing report',
  'page.partners.how_step4_tail':  ' with potential and engaged audience, in an open format.',
  'page.partners.tiers_title':     'Sponsorship tiers',
  'page.partners.tiers_caption':   'Reference values, negotiable. The goal is to sustain the operation: part of the revenue becomes digital marketing that brings more active volunteers.',
  'page.partners.tier_bairro_label':         'Neighborhood Supporter',
  'page.partners.tier_bairro_scope':         '~3 km radius around your business',
  'page.partners.tier_bairro_window':        '1 month',
