  'page.info.ods_caption':         'Bei MAPA FOME kannst du finden, wem du helfen kannst, und neue Markierungen setzen. Wähle die Option, die dich oder eine andere Person darstellt, füge bei Bedarf einen Kontakt hinzu und bestätige mit dem aktuellen Standort oder einer Adresse.',
  'page.info.uses_aria':           'Wofür MAPA FOME da ist',
  'page.info.uses_heading':        'Es dient dazu',
  'page.info.uses_li1':            'Menschen zu erfassen, die auf der Straße oder zu Hause hungern',
  'page.info.uses_li2':            'Initiativen zu erfassen, die Mittel für Spenden erhalten',
  'page.info.uses_li3':            'auf der Karte zu zeigen, wo und wann Essen verteilt wird',
  'page.info.uses_li4':            'gewerbliche oder private Orte zu zeigen, die Freiwillige brauchen, um nicht verbrauchte Lebensmittel abzuholen',
  'page.info.uses_disaster_lead':  'Opfer von Naturkatastrophen zu erfassen und ihnen zu helfen, wie bei der Überschwemmung in Rio Grande do Sul 2024, als sich Betroffene meldeten und den Filter ',
  'page.info.uses_disaster_filter':'Dieses Jahr',
  'page.info.uses_disaster_tail':  ' verlangten. Heute kann man die Karte auch nach Bedürfnissen über Essen hinaus filtern (Wasser, Unterkunft, Kleidung, Hygiene, Medikamente, Tiere und Handy aufladen), denn eine Katastrophe macht Menschen unabhängig vom Einkommen obdachlos',
