  'page.partners.direct_lead':     'Vous préférez un contact direct ? Écrivez à',
  'page.partners.faq_title':       'Questions fréquentes',
  'page.partners.faq1_q':          'Puis-je lancer une campagne pour un seul quartier ?',
  'page.partners.faq1_a_lead':     'Oui, le palier ',
  'page.partners.faq1_a_tail':     ' accepte un rayon de 3 km autour de votre établissement. Vous définissez l\'adresse et la durée.',
  'page.partners.faq2_q':          'Comment prouvez-vous la portée de ma campagne ?',
  'page.partners.faq2_a_lead':     'Sur ',
  'page.partners.faq2_a_tail':     ', ouvert. Nous montrons, par campagne, l\'audience potentielle (points de besoin signalés dans le rectangle temps × espace contracté) et l\'engagée (parmi ceux-ci, combien ont été aidés par un bénévole). Exportable en JSON et CSV.',
  'page.partners.faq3_q':          'Suivez-vous les utilisateurs pour me vendre des données ?',
  'page.partners.faq3_a':          'Non. Jamais. MAPA FOME n\'utilise ni pixel, ni cookie de reciblage, ni device id. Les mesures sont agrégées par territoire et par temps. Les entreprises qui cherchent du reciblage doivent utiliser un autre canal.',
  'page.partners.faq4_q':          'Pouvons-nous contribuer en produit plutôt qu\'en argent ?',
  'page.partners.faq4_a_lead':     'Oui, le palier ',
  'page.partners.faq4_a_tail':     ' accepte les paniers alimentaires, le fret, les heures d\'agence, l\'hébergement cloud, entre autres. Il faut le valoriser dans l\'accord de partenariat pour la comptabilité.',
  'page.partners.faq5_q':          'Ma bannière peut-elle se trouver sur un point de la carte ?',
  'page.partners.faq5_a':          'Non. Aucune bannière n\'apparaît sur la carte ni sur la personne cartographiée. Les slots vivent sur des surfaces institutionnelles (pied de l\'InfoPanel, /apoiar, /iniciativas, /parceiros).',

