  'page.legend.yellow_label':   'Жёлтый',
  'page.legend.yellow_desc':    'Люди в социально уязвимом положении и продовольственной нужде, которые голодают дома или на улице и нуждаются в еде.',
  'page.legend.blue_label':     'Синий',
  'page.legend.blue_desc':      'Люди или инициативы, которые получают еду или ресурсы для раздачи в сообществе (бесплатная столовая, НКО, добровольцы) и нуждаются в пожертвованиях.',
  'page.legend.red_label':      'Красный',
  'page.legend.red_desc':       'Люди или группы, которые раздают еду в постоянной точке на улице в определённый день недели, как пункт выдачи готовой еды.',
  'page.legend.green_label':    'Зелёный',
  'page.legend.green_desc':     'Люди, работающие с едой, которым нужно перенаправить непроданное (ресторан, отель, рынок, супермаркет), и нужны добровольцы, чтобы забрать.',
  'page.creators.heading':      'Создатели контента Mapa Fome',
  'page.creators.iframe_title': 'Creators Mapa Fome',
  'page.thanks.a0':           '[REVISAR-HUMANO] В благодарность за человеческое, нравственное и этическое воспитание, которое я получил от моих школьных учителей философии и социологии.',
  'page.thanks.a1':           '[REVISAR-HUMANO] После 10 лет наблюдения, изучения и осмысления нашей роли как общества у меня появилась возможность действовать, используя накопленные знания и технологии.',
  'page.thanks.a2':           '[REVISAR-HUMANO] И основу для создания проектов (полевые исследования и Project Manager), полученную на курсе Projetão CIn UFPE.',
  'page.thanks.a3':           '[REVISAR-HUMANO] Это привело к тому, что появились нужные инструменты, чтобы действовать в пользу голодающих людей.',
  'page.thanks.a4':           '[REVISAR-HUMANO] И придавать видимость, внося вклад вместе с добрыми людьми, которые регулярно кормят тех, у кого нет денег на еду.',
  'page.thanks.a5':           '[REVISAR-HUMANO] И помогать торговцам продуктами сокращать пищевые отходы.',
  'page.thanks.a6':           '[REVISAR-HUMANO] И мотивировать и предлагать инструменты, чтобы каждый человек делал свою часть и помогал на регулярной основе.',
  'page.thanks.a7':           '[REVISAR-HUMANO] Или, если не едой, то обменом информацией, рассказывая о существовании MAPA FOME тем, кто в нём нуждается, и тем, кто может помочь.',
  'page.thanks.a8':           '[REVISAR-HUMANO] Без еды любой человек умирает преждевременно. Неоказание помощи, когда это возможно без риска для себя, образует преступление неоказания помощи (ст. 135 Уголовного кодекса Бразилии).',
  'page.thanks.doc_lead':       '[REVISAR-HUMANO] За то, что показали отмеченный наградами 13-минутный короткометражный документальный фильм бразильца Жоржи Фуртаду,',
  'page.timeline.t0_time':    '0–3 horas',
  'page.timeline.t0_conseq':  'Минимальные изменения.',
  'page.timeline.t1_time':    '4–8 horas',
  'page.timeline.t1_conseq':  'Сильнее голод, лёгкая боль в животе, возможна головная боль.',
  'page.timeline.t2_time':    '9–12 horas',
  'page.timeline.t2_conseq':  'Усталость, раздражительность, стресс и головная боль.',
  'page.timeline.t3_time':    '13–16 horas',
  'page.timeline.t3_conseq':  'Трудно быть внимательным и сосредоточиться.',
  'page.timeline.t4_time':    '17–24 horas',
  'page.timeline.t4_conseq':  'Не хватает сахара в организме: головокружение или дрожь.',
  'page.timeline.t5_time':    '25–48 horas',
  'page.timeline.t5_conseq':  'Слабость и режим выживания: сердце бьётся быстрее из-за нехватки энергии.',
  'page.timeline.t6_time':    '49–72 horas',
  'page.timeline.t6_conseq':  'Организм начинает использовать запасы жира; иммунитет слабеет.',
  'page.timeline.t7_time':    '3–7 dias',
  'page.timeline.t7_conseq':  'Мышцы начинают расходоваться как энергия. Снижение мотивации и продуктивности.',
  'page.timeline.t8_time':    '8–14 dias',
  'page.timeline.t8_conseq':  'Органы начинают страдать, и человек заболевает гораздо легче.',
  'page.timeline.t9_time':    '15–21 dias',
  'page.timeline.t9_conseq':  'Жизнь в опасности.',
  'page.timeline.t10_time':    '22+ dias',
  'page.timeline.t10_conseq':  'Крайняя опасность: органы могут перестать работать в любой момент.',
