  'page.hungertable.conseq_1':   'Вы почувствуете больший голод, и живот будет немного болеть, может появиться головная боль',
  'page.hungertable.conseq_2':   'Вы начнёте чувствовать усталость и раздражительность, злость, нервозность, стресс, и у вас будет болеть голова',
  'page.hungertable.conseq_3':   'станет труднее быть внимательным и сосредотачиваться',
  'page.hungertable.conseq_4':   'В организме не будет хватать сахара, из-за чего вы почувствуете головокружение или ДРОЖЬ',
  'page.hungertable.conseq_5':   'Вы почувствуете слабость и окажетесь в ситуации сильного стресса и в режиме выживания, сердце будет биться быстрее, потому что не хватает энергии из пищи, поэтому оно пытается работать вдвойне, чтобы сохранить результат (доставку кислорода и питательных веществ к жизненно важным органам)',
  'page.hungertable.conseq_6':   'Организм начнёт использовать запасённую энергию (жир,...), из-за чего вы почувствуете усталость, а иммунная система будет работать хуже, вы легче заболеваете',
  'page.hungertable.conseq_7':   'Мышцы начинают расходоваться как энергия, вы почувствуете сильную слабость, и мышцы уменьшатся. Это плохо для организма, наносит ему вред. Снижение мотивации или продуктивности',
  'page.hungertable.conseq_8':   'Ваши органы, важные части тела, будут повреждены, и вы будете болеть гораздо легче',
