  'page.creators.heading':      'Mapa Fome 内容创作者',
  'page.creators.iframe_title': 'Creators Mapa Fome',
  'page.thanks.a0':           '[REVISAR-HUMANO] 感谢我高中的哲学和社会学老师给予我的人文、道德与伦理培养。',
  'page.thanks.a1':           '[REVISAR-HUMANO] 在观察、学习并内化我们作为社会一员的角色十年之后，我有机会运用积累的知识和技术去行动。',
  'page.thanks.a2':           '[REVISAR-HUMANO] 以及在 Projetão CIn UFPE 课程中获得的创建项目（实地研究与项目管理）的基础。',
  'page.thanks.a3':           '[REVISAR-HUMANO] 这让我获得了为挨饿的人们行动所需的工具。',
  'page.thanks.a4':           '[REVISAR-HUMANO] 并提升关注度，与那些常年为买不起食物的人提供食物的善心人士一起贡献力量。',
  'page.thanks.a5':           '[REVISAR-HUMANO] 并帮助食品商家减少浪费。',
  'page.thanks.a6':           '[REVISAR-HUMANO] 并激励人们、提供工具，让每个人都尽自己的一份力，持续地参与帮助。',
  'page.thanks.a7':           '[REVISAR-HUMANO] 或者，如果不能用食物，就通过分享信息，把 MAPA FOME 的存在告诉需要它的人和能够帮助的人。',
  'page.thanks.a8':           '[REVISAR-HUMANO] 没有食物，任何人都会过早死亡。在能够不冒个人风险的情况下却不予以救助，构成见危不救罪（巴西刑法第 135 条）。',
  'page.thanks.doc_lead':       '[REVISAR-HUMANO] 感谢他们播出了巴西人 Jorge Furtado 那部获奖的 13 分钟短纪录片，',
