  // ── home: CreatorsMapaFome.js ──
  'page.creators.heading':      'صنّاع محتوى Mapa Fome',
  'page.creators.iframe_title': 'Creators Mapa Fome',
  'page.thanks.a0':           '[REVISAR-HUMANO] عرفانًا بالتكوين الإنساني والأخلاقي الذي تلقّيته من أساتذتي في الفلسفة وعلم الاجتماع في المرحلة الثانوية.',
  'page.thanks.a1':           '[REVISAR-HUMANO] بعد 10 سنوات من المشاهدة والتعلّم واستيعاب دورنا كمجتمع، أتيحت لي الفرصة للتصرّف باستخدام المعرفة والتقنيات المتراكمة.',
  'page.thanks.a2':           '[REVISAR-HUMANO] والأساس لإنشاء المشاريع (البحث الميداني وإدارة المشاريع) المكتسب في مادة Projetão CIn UFPE.',
  'page.thanks.a3':           '[REVISAR-HUMANO] أدّى ذلك إلى الحصول على الأدوات اللازمة للعمل لصالح من يعانون الجوع.',
  'page.thanks.a4':           '[REVISAR-HUMANO] ولإبراز ذلك، بالمساهمة جنبًا إلى جنب مع أصحاب القلوب الطيبة الذين يُطعمون باستمرار من لا يملكون المال لشراء الطعام.',
  'page.thanks.a5':           '[REVISAR-HUMANO] ولمساعدة تجّار الطعام على تقليل الهدر.',
  'page.thanks.a6':           '[REVISAR-HUMANO] ولتحفيز كل إنسان وتقديم الأدوات له ليقوم بدوره ويتعاون بشكل متكرّر.',
  'page.thanks.a7':           '[REVISAR-HUMANO] أو، إن لم يكن بالطعام، فبمشاركة المعلومات، بإعلام من يحتاج ومن يستطيع المساعدة بوجود MAPA FOME.',
  'page.thanks.a8':           '[REVISAR-HUMANO] بدون طعام، يموت أي إنسان مبكرًا. الامتناع عن تقديم المساعدة، حين يمكن ذلك دون خطر شخصي، يُشكّل جريمة الامتناع عن الإغاثة (المادة 135 من قانون العقوبات البرازيلي).',
  'page.thanks.doc_lead':       '[REVISAR-HUMANO] لعرضهم الفيلم الوثائقي القصير الحائز على جوائز ومدته 13 دقيقة للبرازيلي Jorge Furtado،',
