  'page.creators.heading':      'Mapa Fome কনটেন্ট ক্রিয়েটর',
  'page.creators.iframe_title': 'Creators Mapa Fome',
  'page.thanks.a0':           '[REVISAR-HUMANO] উচ্চ বিদ্যালয়ের আমার দর্শন ও সমাজবিজ্ঞান শিক্ষকদের কাছ থেকে পাওয়া মানবিক, নৈতিক ও আদর্শিক গঠনের প্রতি কৃতজ্ঞতায়.',
  'page.thanks.a1':           '[REVISAR-HUMANO] সমাজ হিসেবে আমাদের ভূমিকা দেখা, শেখা ও অভ্যন্তরীণ করার 10 বছর পর, সঞ্চিত জ্ঞান ও প্রযুক্তি ব্যবহার করে কাজ করার সুযোগ পেয়েছিলাম.',
  'page.thanks.a2':           '[REVISAR-HUMANO] এবং প্রকল্প তৈরির ভিত্তি (মাঠ গবেষণা ও Project Manager) Projetão CIn UFPE কোর্সে অর্জিত.',
  'page.thanks.a3':           '[REVISAR-HUMANO] এতে ক্ষুধার্ত মানুষের পক্ষে কাজ করার প্রয়োজনীয় সরঞ্জাম পাওয়া গেল.',
  'page.thanks.a4':           '[REVISAR-HUMANO] এবং দৃশ্যমানতা দিতে, সেই সদয় হৃদয়ের মানুষদের সাথে অবদান রেখে যারা নিয়মিত তাদের খাওয়ান যাদের খাবার কেনার অর্থ নেই.',
  'page.thanks.a5':           '[REVISAR-HUMANO] এবং খাদ্য ব্যবসায়ীদের অপচয় কমাতে সাহায্য করতে.',
  'page.thanks.a6':           '[REVISAR-HUMANO] এবং প্রতিটি মানুষকে তার অংশ করতে ও নিয়মিতভাবে সহযোগিতা করতে উদ্বুদ্ধ করতে ও সরঞ্জাম দিতে.',
  'page.thanks.a7':           '[REVISAR-HUMANO] অথবা, খাবার দিয়ে না হলে, তথ্য শেয়ার করে, যাদের প্রয়োজন ও যারা সাহায্য করতে পারেন তাদের MAPA FOME-এর অস্তিত্ব জানিয়ে.',
  'page.thanks.a8':           '[REVISAR-HUMANO] খাবার ছাড়া যেকোনো মানুষ অকালে মারা যায়. ব্যক্তিগত ঝুঁকি ছাড়া সম্ভব হলে সাহায্য না করা ব্রাজিলীয় দণ্ডবিধির 135 অনুচ্ছেদ অনুযায়ী সাহায্যে অবহেলার অপরাধ গঠন করে.',
  'page.thanks.doc_lead':       '[REVISAR-HUMANO] ব্রাজিলীয় Jorge Furtado-এর পুরস্কারপ্রাপ্ত 13 মিনিটের স্বল্পদৈর্ঘ্য তথ্যচিত্রটি প্রচার করার জন্য,',
