  'page.hungertable.conseq_7':   'পেশি শক্তি হিসেবে ক্ষয় হতে শুরু করে, আপনি খুব দুর্বল বোধ করবেন এবং আপনার পেশি সংকুচিত হবে. এটি আপনার শরীরের জন্য ভালো নয়, এটি দেহকে ক্ষতি করে. অনুপ্রেরণা বা উৎপাদনশীলতা কমে',
