  'page.press.lead':               'এই পৃষ্ঠা সাংবাদিক, কনটেন্ট ক্রিয়েটর ও অংশীদারদের MAPA FOME নিয়ে কথা বলতে যা প্রয়োজন তা একত্র করে, আমাদের আগে লেখার দরকার ছাড়াই. লোগো ডাউনলোড করুন, প্রস্তুত বিবরণ কপি করুন, ফ্যাক্ট শিট, রঙ ও ব্যবহারের নিয়ম দেখুন, এবং উদ্ধৃতিযোগ্য লাইন নিন. এটি বিনামূল্যে ও সম্পাদকীয় ব্যবহারের জন্য মুক্ত, কৃতিত্বসহ. বিনিময়ে আমরা কেবল একটি জিনিস চাই: যাদের মানচিত্রিত করা হয় তাদের মর্যাদাকে সম্মান করুন, তারা নাগরিকদের সাথে সংযোগকারী নাগরিক, শিকার বা দাতব্য ঘটনা নয়. MAPA FOME কাউকে প্রতিস্থাপন করে না, সবাইকে সংযুক্ত করে.',
  'page.press.intro_title':        'MAPA FOME কী',
  'page.press.icon_alt':           'MAPA FOME আইকন',
  'page.press.eyebrow':            'প্রস্তাব',
  'page.press.intro_body':         'MAPA FOME একটি সহযোগিতামূলক, সর্বজনীন, বিনামূল্যের ও বেনামি মানচিত্র. তিন চাপে, যে কেউ মানচিত্রে ক্ষুধার সম্মুখীন কাউকে চিহ্নিত করে যাতে কাছের স্বেচ্ছাসেবকরা রিয়েল টাইমে সাহায্য আনেন. এটি মুক্ত সফটওয়্যার, উন্মুক্ত ডেটাসহ, Recife-এ জন্ম, 2022 সালে CIn UFPE-তে কম্পিউটার বিজ্ঞান ডিগ্রির সময় উদ্ভূত, এবং ব্রাজিল জুড়ে বিস্তৃত হচ্ছে. অনালোচনাযোগ্য নীতি: আমরা মানুষকে সাহায্য করি, মানুষকে নজরদারি করি না.',
