  // ── home: CreatorsMapaFome.js ──
  'page.creators.heading':      'Творці контенту Mapa Fome',
  'page.creators.iframe_title': 'Creators Mapa Fome',
  'page.thanks.a0':           '[REVISAR-HUMANO] На знак вдячності за людське, моральне та етичне формування, яке я отримав від моїх шкільних учителів філософії та соціології.',
  'page.thanks.a1':           '[REVISAR-HUMANO] Після 10 років спостереження, навчання та усвідомлення нашої ролі як суспільства я мав змогу діяти, використовуючи накопичені знання й технології.',
  'page.thanks.a2':           '[REVISAR-HUMANO] І основу для створення проєктів (польове дослідження та Project Manager), здобуту на курсі Projetão CIn UFPE.',
  'page.thanks.a3':           '[REVISAR-HUMANO] Це привело до отримання інструментів, потрібних, щоб діяти на користь людей, які голодують.',
  'page.thanks.a4':           '[REVISAR-HUMANO] І щоб надати видимість, роблячи внесок разом із добросердими людьми, які регулярно годують тих, хто не має грошей купити їжу.',
  'page.thanks.a5':           '[REVISAR-HUMANO] І щоб допомогти торговцям їжею зменшити відходи.',
  'page.thanks.a6':           '[REVISAR-HUMANO] І щоб мотивувати та надати інструменти кожній людині робити свою частину й співпрацювати регулярно.',
  'page.thanks.a7':           '[REVISAR-HUMANO] Або, якщо не їжею, то поширенням інформації, повідомляючи про існування MAPA FOME тим, хто потребує, і тим, хто може допомогти.',
  'page.thanks.a8':           '[REVISAR-HUMANO] Без їжі будь-яка людина передчасно гине. Ненадання допомоги, коли це можливо без особистого ризику, утворює злочин ненадання допомоги (стаття 135 Кримінального кодексу Бразилії).',
  'page.thanks.doc_lead':       '[REVISAR-HUMANO] За те, що показали відзначений нагородами 13-хвилинний короткометражний документальний фільм бразильця Jorge Furtado,',
