  // ── route page: /imprensa ──
  'page.press.back':               '← Карта',
  'page.press.title':              'Прескіт MAPA FOME',
  'page.press.lead':               'Ця сторінка збирає все, що потрібно журналістам, творцям контенту та партнерам, щоб говорити про MAPA FOME, не пишучи нам спершу. Завантажте логотипи, скопіюйте готові описи, перегляньте технічну довідку, кольори та правила використання й візьміть цитовані рядки. Це безкоштовно й вільно для редакційного використання, з посиланням. Просимо лише одне натомість: поважайте гідність тих, кого позначено, це громадяни, що з’єднують громадян, не жертви й не випадки благодійності. MAPA FOME нікого не заміняє, він з’єднує всіх.',
  'page.press.intro_title':        'Що таке MAPA FOME',
  'page.press.icon_alt':           'Іконка MAPA FOME',
  'page.press.eyebrow':            'Пропозиція',
  'page.press.intro_body':         'MAPA FOME, це спільна, публічна, безкоштовна й анонімна карта. За три дотики будь-хто позначає на карті того, хто стикається з голодом, щоб найближчі волонтери принесли допомогу в реальному часі. Це вільне програмне забезпечення з відкритими даними, народжене в Recife, що виникло 2022 року під час навчання з комп’ютерних наук у CIn UFPE й розширюється по Бразилії. Принцип без обговорення: ми допомагаємо людям, не стежимо за людьми.',
  'page.press.framing':            'Пропоноване обрамлення: громадянська технологія та солідарність між сусідами, не благодійність і не жалість.',
  'page.press.slogan':             '"Спільна карта. Відкрита. У реальному часі."',
  'page.press.subtagline':         '"Нікого не заміняє. З’єднує всіх."',
  'page.press.quick_title':        'Найголовніше за 30 секунд',
  'page.press.refusals_title':     'Що MAPA FOME відмовляється робити',
  'page.press.refusals_intro':     'Те, що ми відкидаємо, визначає проєкт не менше, ніж те, що ми пропонуємо. Ці рядки без обговорення.',
  'page.press.refusals_callout':   '"Ми позначаємо голод, щоб його скоротити, ніколи, щоб стежити за тим, хто його відчуває."',
  'page.press.assets_title':       'Логотипи та ресурси для завантаження',
  'page.press.assets_note_lead':   'Формати: PNG (прозорий) для швидкого використання, SVG (вектор) для друку й будь-якого розміру без втрати чіткості. Потрібен інший формат, фон чи монохромна версія? Напишіть на ',
