  // ── home: infoPanelContent.js — LEGEND ──
  'page.legend.yellow_label':   'पीले में',
  'page.legend.yellow_desc':    'सामाजिक रूप से असुरक्षित और खाद्य असुरक्षा झेल रहे लोग जो घर पर या सड़क पर भूखे हैं और जिन्हें भोजन की ज़रूरत है।',
  'page.legend.blue_label':     'नीले में',
  'page.legend.blue_desc':      'ऐसे लोग या पहलें जो समुदाय में बाँटने के लिए भोजन या संसाधन लेते हैं (सामुदायिक रसोई, एनजीओ, स्वयंसेवक) और जिन्हें दान की ज़रूरत है।',
  'page.legend.red_label':      'लाल में',
  'page.legend.red_desc':       'ऐसे लोग या समूह जो सप्ताह के किसी निश्चित दिन सड़क पर एक स्थायी बिंदु पर भोजन पहुँचाते हैं, तैयार भोजन वितरण बिंदु की तरह।',
  'page.legend.green_label':    'हरे में',
  'page.legend.green_desc':     'ऐसे लोग जो भोजन से जुड़े काम करते हैं और जिन्हें बिना बिके बचे भोजन को सौंपना होता है (रेस्तराँ, होटल, बाज़ार, सुपरमार्केट) और जिन्हें उसे लेने के लिए स्वयंसेवकों की ज़रूरत है।',
  // ── home: CreatorsMapaFome.js ──
  'page.creators.heading':      'Mapa Fome के कंटेंट निर्माता',
  'page.creators.iframe_title': 'Creators Mapa Fome',
  'page.thanks.a0':           '[REVISAR-HUMANO] हाई स्कूल में दर्शनशास्त्र और समाजशास्त्र के मेरे शिक्षकों से मुझे जो मानवीय, नैतिक और सदाचारी शिक्षा मिली, उसके आभार में।',
  'page.thanks.a1':           '[REVISAR-HUMANO] एक समाज के रूप में हमारी भूमिका को देखने, सीखने और आत्मसात करने के 10 वर्षों के बाद, मुझे संचित ज्ञान और तकनीकों का उपयोग करके कार्य करने का अवसर मिला।',
  'page.thanks.a2':           '[REVISAR-HUMANO] और परियोजनाएँ बनाने का आधार (क्षेत्र अनुसंधान और Project Manager), जो Projetão CIn UFPE पाठ्यक्रम में प्राप्त हुआ।',
  'page.thanks.a3':           '[REVISAR-HUMANO] इससे भूख झेलने वाले लोगों के पक्ष में कार्य करने के लिए ज़रूरी उपकरण मिले।',
  'page.thanks.a4':           '[REVISAR-HUMANO] और दृश्यता देने के लिए, उन अच्छे दिल वाले लोगों के साथ योगदान करते हुए जो नियमित रूप से उन्हें भोजन देते हैं जिनके पास भोजन ख़रीदने के पैसे नहीं हैं।',
  'page.thanks.a5':           '[REVISAR-HUMANO] और खाद्य व्यापारियों को बर्बादी कम करने में योगदान देने के लिए।',
  'page.thanks.a6':           '[REVISAR-HUMANO] और हर मनुष्य को अपना हिस्सा निभाने और नियमित रूप से सहयोग करने के लिए प्रेरित करने तथा उपकरण देने के लिए।',
  'page.thanks.a7':           '[REVISAR-HUMANO] या, अगर भोजन से नहीं, तो जानकारी साझा करके, MAPA FOME के अस्तित्व की सूचना उन्हें देकर जिन्हें ज़रूरत है और जो मदद कर सकते हैं।',
  'page.thanks.a8':           '[REVISAR-HUMANO] भोजन के बिना कोई भी मनुष्य असमय मर जाता है। जब व्यक्तिगत जोखिम के बिना सहायता देना संभव हो, तब उसे न देना सहायता-त्याग का अपराध है (ब्राज़ीली दंड संहिता का अनुच्छेद 135)।',
  'page.thanks.doc_lead':       '[REVISAR-HUMANO] ब्राज़ीली Jorge Furtado की पुरस्कृत 13 मिनट की लघु डॉक्यूमेंट्री दिखाने के लिए,',
  'page.timeline.t0_time':    '0–3 horas',
  'page.timeline.t0_conseq':  'न्यूनतम बदलाव।',
  'page.timeline.t1_time':    '4–8 horas',
  'page.timeline.t1_conseq':  'अधिक भूख, पेट में हल्का दर्द, संभव सिरदर्द।',
  'page.timeline.t2_time':    '9–12 horas',
  'page.timeline.t2_conseq':  'थकान, चिड़चिड़ापन, तनाव और सिरदर्द।',
  'page.timeline.t3_time':    '13–16 horas',
  'page.timeline.t3_conseq':  'ध्यान देने और एकाग्र होने में कठिनाई।',
  'page.timeline.t4_time':    '17–24 horas',
  'page.timeline.t4_conseq':  'शरीर में शर्करा की कमी: चक्कर या कँपकँपी।',
  'page.timeline.t5_time':    '25–48 horas',
  'page.timeline.t5_conseq':  'कमज़ोरी और उत्तरजीविता मोड: ऊर्जा की कमी से दिल तेज़ धड़कता है।',
  'page.timeline.t6_time':    '49–72 horas',
  'page.timeline.t6_conseq':  'शरीर संचित वसा का उपयोग करने लगता है, रोग प्रतिरोधक क्षमता कमज़ोर पड़ती है।',
  'page.timeline.t7_time':    '3–7 dias',
  'page.timeline.t7_conseq':  'मांसपेशियाँ ऊर्जा के रूप में खर्च होने लगती हैं। प्रेरणा और उत्पादकता घटती है।',
  'page.timeline.t8_time':    '8–14 dias',
  'page.timeline.t8_conseq':  'अंग प्रभावित होने लगते हैं और व्यक्ति कहीं अधिक आसानी से बीमार पड़ता है।',
  'page.timeline.t9_time':    '15–21 dias',
  'page.timeline.t9_conseq':  'जीवन ख़तरे में है।',
  'page.timeline.t10_time':    '22+ dias',
  'page.timeline.t10_conseq':  'अत्यधिक ख़तरा: अंग किसी भी क्षण काम करना बंद कर सकते हैं।',
  'page.info.intro_lead':       'मानचित्र पर मदद का तरीक़ा जानने के लिए किसी गोले पर क्लिक करें। आप ख़ुद को या किसी और को जोड़ सकते हैं: स्थिति चुनें और स्थान की पुष्टि करें।',
  'page.info.intro_globo':      'Globo की रिपोर्ट में',

  // ── LOCATION-GEOFENCE ──
