  'page.geofence.country_mismatch': '[REVISAR-HUMANO] हम केवल उसी देश में जगहें अंकित कर सकते हैं जहाँ आप वास्तव में हैं। ऐसा लगता है कि आपका स्थान और आपकी इंटरनेट पहुँच अलग-अलग देशों में हैं।',
  'page.geofence.controls_hidden': '[REVISAR-HUMANO] बिंदु जोड़ने के लिए, पहले हमें पुष्टि करनी होगी कि आप अपने देश में हैं। स्थान चालू करें और अपना कनेक्शन जाँचें।',
