  'page.hungertable.conseq_4':   'आपके शरीर में पर्याप्त शर्करा नहीं होगी, जिससे आपको चक्कर आएगा या कँपकँपी होगी',
  'page.hungertable.conseq_5':   'आप कमज़ोर महसूस करेंगे और उच्च तनाव तथा उत्तरजीविता मोड में चले जाएँगे, ऊर्जा की कमी के कारण आपका दिल तेज़ धड़केगा क्योंकि भोजन से मिलने वाली ऊर्जा कम है, इसलिए वह परिणाम (महत्वपूर्ण अंगों तक ऑक्सीजन और पोषक तत्व पहुँचाना) बनाए रखने के लिए दोगुना काम करने की कोशिश करता है',
  'page.hungertable.conseq_6':   'आपका शरीर संचित ऊर्जा (वसा,...) का उपयोग करने लगेगा, जिससे आप थका हुआ महसूस करेंगे और आपकी रोग प्रतिरोधक क्षमता उतनी अच्छी नहीं रहेगी, आप अधिक आसानी से बीमार पड़ेंगे',
  'page.hungertable.conseq_7':   'मांसपेशियाँ ऊर्जा के रूप में खर्च होने लगती हैं, आप बहुत कमज़ोर महसूस करेंगे और आपकी मांसपेशियाँ घटेंगी। यह आपके शरीर के लिए अच्छा नहीं है, यह शरीर को नुक़सान पहुँचाता है। प्रेरणा या उत्पादकता में कमी',
  'page.hungertable.conseq_8':   'आपके अंग, जो आपके शरीर के अहम हिस्से हैं, क्षतिग्रस्त होंगे और आप कहीं अधिक आसानी से बीमार पड़ेंगे',
  'page.hungertable.conseq_9':   'आप बहुत बीमार पड़ेंगे और आपका जीवन ख़तरे में होगा',
