  // ── home: PressKitPage.js ──
  'page.press.back':             '← मानचित्र',
  'page.press.title':            'MAPA FOME का प्रेस किट',
  'page.press.lead':             'यह पृष्ठ वह सब जुटाता है जो पत्रकारों, कंटेंट निर्माताओं और साझेदारों को MAPA FOME के बारे में बात करने के लिए चाहिए, बिना हमें पहले लिखे। लोगो डाउनलोड करें, तैयार विवरण कॉपी करें, तकनीकी ब्योरा, रंग और उपयोग नियम देखें, और उद्धरण योग्य वाक्य लें। यह मुफ़्त है और श्रेय के साथ संपादकीय उपयोग के लिए स्वतंत्र है। बदले में हम केवल एक बात माँगते हैं: अंकित लोगों की गरिमा का सम्मान करें, वे नागरिक हैं जो नागरिकों को जोड़ते हैं, न पीड़ित न दान के मामले। MAPA FOME किसी की जगह नहीं लेता; सबको जोड़ता है।',
  'page.press.intro_title':      'MAPA FOME क्या है',
  'page.press.icon_alt':         'MAPA FOME का आइकन',
  'page.press.eyebrow':          'प्रस्ताव',
  'page.press.intro_body':       'MAPA FOME एक सहयोगी, सार्वजनिक, मुफ़्त और गुमनाम मानचित्र है। तीन टैप में, कोई भी व्यक्ति भूख की स्थिति में किसी को मानचित्र पर अंकित करता है ताकि पास के स्वयंसेवक वास्तविक समय में मदद पहुँचाएँ। यह मुक्त सॉफ़्टवेयर है, खुले डेटा के साथ, Recife में जन्मा, 2022 में CIn UFPE में कंप्यूटर विज्ञान की पढ़ाई के दौरान शुरू हुआ, और ब्राज़ील भर में फैल रहा है। अपरिवर्तनीय सिद्धांत: हम लोगों की मदद करते हैं, उनकी निगरानी नहीं।',
  'page.press.framing':          'सुझाया गया ढाँचा: नागरिक तकनीक और पड़ोसियों के बीच एकजुटता, न दान न दया।',
  'page.press.slogan':           '“एक सहयोगी मानचित्र। खुला। वास्तविक समय में।”',
  'page.press.subtagline':       '“किसी की जगह नहीं लेता। सबको जोड़ता है।”',
  'page.press.quick_title':      '30 सेकंड में मुख्य बातें',
  'page.press.refusals_title':   'MAPA FOME क्या करने से इनकार करता है',
  'page.press.refusals_intro':   'जो हम अस्वीकार करते हैं वह परियोजना को उतना ही परिभाषित करता है जितना जो हम देते हैं। ये पंक्तियाँ अपरिवर्तनीय हैं।',
  'page.press.refusals_callout': '“हम भूख को छोटा करने के लिए उसका मानचित्र बनाते हैं, उसे झेलने वाले की निगरानी के लिए कभी नहीं।”',
