  'page.creators.iframe_title': 'Creators Mapa Fome',
  'page.thanks.a0':           '[REVISAR-HUMANO] Lisede Felsefe ve Sosyoloji öğretmenlerimden aldığım insani, ahlaki ve etik oluşuma şükranla.',
  'page.thanks.a1':           '[REVISAR-HUMANO] Bir toplum olarak rolümüzü 10 yıl boyunca izledikten, öğrendikten ve içselleştirdikten sonra, biriken bilgi ve teknolojileri kullanarak harekete geçme fırsatı buldum.',
  'page.thanks.a2':           '[REVISAR-HUMANO] Ve Projetão CIn UFPE dersinde edinilen, projeler oluşturma temeli (saha araştırması ve Project Manager).',
  'page.thanks.a3':           '[REVISAR-HUMANO] Bu, açlık çeken insanlar lehine harekete geçmek için gereken araçları elde etmeyle sonuçlandı.',
  'page.thanks.a4':           '[REVISAR-HUMANO] Ve görünürlük kazandırmak için, yemek alacak parası olmayanları düzenli olarak besleyen iyi kalpli insanlarla birlikte katkı sunarak.',
  'page.thanks.a5':           '[REVISAR-HUMANO] Ve gıda esnafının israfı azaltmasına katkıda bulunmak için.',
  'page.thanks.a6':           '[REVISAR-HUMANO] Ve her insanı kendi payına düşeni yapmaya ve düzenli olarak iş birliği yapmaya teşvik etmek ve araç sunmak için.',
  'page.thanks.a7':           '[REVISAR-HUMANO] Ya da yemekle olmasa bile, bilgiyi paylaşarak, MAPA FOME’nin varlığını ihtiyacı olana ve yardım edebilecek olana bildirerek.',
  'page.thanks.a8':           '[REVISAR-HUMANO] Yemek olmadan herhangi bir insan vaktinden önce ölür. Kişisel risk olmadan yapılabilecekken yardım etmemek, yardımı esirgeme suçunu oluşturur (Brezilya Ceza Kanunu’nun 135. maddesi).',
  'page.thanks.doc_lead':       '[REVISAR-HUMANO] Brezilyalı Jorge Furtado’nun ödüllü 13 dakikalık kısa belgeselini gösterdikleri için,',
