  // ── home: PressKitPage.js ──
  'page.press.back':             '← Harita',
  'page.press.title':            'MAPA FOME basın kiti',
  'page.press.lead':             'Bu sayfa, gazetecilerin, içerik üreticilerinin ve iş ortaklarının MAPA FOME hakkında konuşmak için ihtiyaç duyduğu her şeyi, önceden bize yazmadan bir araya getirir. Logoları indirin, hazır açıklamaları kopyalayın, teknik bilgileri, renkleri ve kullanım kurallarını inceleyin ve alıntılanabilir cümleler alın. Ücretsizdir ve atıfla editöryel kullanım için serbesttir. Karşılığında yalnızca bir şey isteriz: işaretlenenlerin onuruna saygı gösterin, onlar vatandaşları birbirine bağlayan vatandaşlardır, ne kurban ne hayır işi vakaları. MAPA FOME kimsenin yerini almaz; herkesi birbirine bağlar.',
  'page.press.intro_title':      'MAPA FOME nedir',
  'page.press.icon_alt':         'MAPA FOME simgesi',
  'page.press.eyebrow':          'Öneri',
  'page.press.intro_body':       'MAPA FOME işbirlikçi, kamuya açık, ücretsiz ve anonim bir haritadır. Üç dokunuşta, herhangi biri açlık durumundaki birini haritada işaretler, böylece yakındaki gönüllüler gerçek zamanlı yardım götürür. Özgür yazılımdır, açık verilidir, Recife’de doğdu, 2022’de CIn UFPE’de Bilgisayar Bilimi lisansı sırasında başladı ve Brezilya genelinde yayılıyor. Pazarlığa kapalı ilke: insanlara yardım ederiz, insanları gözetlemeyiz.',
  'page.press.framing':          'Önerilen çerçeve: sivil teknoloji ve komşular arası dayanışma, hayır ya da acıma değil.',
  'page.press.slogan':           '“İşbirlikçi bir harita. Açık. Gerçek zamanlı.”',
  'page.press.subtagline':       '“Kimsenin yerini almaz. Herkesi birbirine bağlar.”',
  'page.press.quick_title':      '30 saniyede temel bilgiler',
  'page.press.refusals_title':   'MAPA FOME’nin yapmayı reddettikleri',
  'page.press.refusals_intro':   'Reddettiklerimiz projeyi en az sunduklarımız kadar tanımlar. Bu çizgiler pazarlığa kapalıdır.',
  'page.press.refusals_callout': '“Açlığı kısaltmak için haritalıyoruz, onu hissedeni gözetlemek için asla.”',
  'page.press.assets_title':     'İndirmek için logolar ve varlıklar',
  'page.press.assets_note_lead': 'Biçimler: hızlı kullanım için PNG (saydam); baskı ve netliği yitirmeden her boyut için SVG (vektör). Başka bir biçim, arka plan ya da tek renkli sürüm mü lazım? Şuraya yazın ',
  'page.press.license_title':    'Varlıkların kullanım koşulları',
  'page.press.license_intro_lead':'MAPA FOME varlıklarını proje hakkındaki haberlerde, gönderilerde, videolarda ve tanıtım materyallerinde serbestçe kullanabilirsiniz, her zaman şuna atıfla ',
  'page.press.license_intro_tail':'.',
